-- Isolated PostgreSQL fixture for the Advanced Combinations migration tests.
-- This file is used only by GitHub Actions' disposable PostgreSQL service.

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
    CREATE ROLE anon NOLOGIN;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
    CREATE ROLE authenticated NOLOGIN;
  END IF;
END
$$;

CREATE SCHEMA IF NOT EXISTS auth;

CREATE OR REPLACE FUNCTION auth.uid()
RETURNS uuid
LANGUAGE sql
STABLE
AS $$
  SELECT NULLIF(current_setting('request.jwt.claim.sub', true), '')::uuid
$$;

CREATE TABLE public.schools (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  school_name text NOT NULL
);

CREATE TABLE public.profiles (
  id uuid PRIMARY KEY,
  school_id bigint
);

CREATE TABLE public.classes (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  school_id bigint NOT NULL,
  academic_level text NOT NULL,
  class_name text NOT NULL
);

CREATE TABLE public.subjects (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  subject_name text NOT NULL,
  subject_code text,
  education_level text NOT NULL DEFAULT 'Advanced',
  is_active boolean NOT NULL DEFAULT true
);

CREATE TABLE public.students (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  school_id bigint NOT NULL,
  current_class_id bigint NOT NULL
);

INSERT INTO public.schools (id, school_name) VALUES
  (1, 'Test School A'),
  (2, 'Test School B');

INSERT INTO public.profiles (id, school_id) VALUES
  ('11111111-1111-4111-8111-111111111111', 1),
  ('22222222-2222-4222-8222-222222222222', 2);

INSERT INTO public.classes (id, school_id, academic_level, class_name) VALUES
  (1, 1, 'Advanced', 'Form 5 A'),
  (2, 2, 'Advanced', 'Form 5 B'),
  (3, 1, 'Ordinary', 'Form 4 A');

INSERT INTO public.subjects (id, subject_name, subject_code, education_level) VALUES
  (1, 'Physics', 'PHY', 'Advanced'),
  (2, 'Chemistry', 'CHE', 'Advanced'),
  (3, 'Biology', 'BIO', 'Advanced');

GRANT USAGE ON SCHEMA public, auth TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO authenticated;
GRANT EXECUTE ON FUNCTION auth.uid() TO authenticated;
